/bin/bash -lc "python - <<'PY'
import json, urllib.request
for repo in ['phykit','python']:
    url=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/?limit=8'
    try:
        data=json.load(urllib.request.urlopen(url, timeout=20))
        print(repo)
        for t in data.get('tags',[])[:8]: print(' ', t.get('name'))
    except Exception as e:
        print(repo, 'ERROR', type(e).__name__, str(e))
PY"

